import { revalidateTag } from 'next/cache';
import { after } from 'next/server';
import { getProducts } from '@/lib/products';

export default async function AdminCatalogPage() {
  const products = await getProducts();

  async function syncCatalog() {
    'use server';
    // Schedule cache invalidation to run after the response is sent so the
    // admin is never blocked waiting for the re-fetch. The stale cached data
    // is returned immediately; any subsequent request to a view that depends
    // on the "products" tag will pick up the fresh data.
    after(() => revalidateTag('products'));
  }

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem', maxWidth: '900px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <h1 style={{ margin: 0, fontSize: '1.5rem' }}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1.25rem',
              backgroundColor: '#0070f3',
              color: '#fff',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontSize: '0.875rem',
              fontWeight: 500,
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #eaeaea' }}>
            <th style={{ textAlign: 'left', padding: '0.625rem 0.75rem', color: '#666', fontWeight: 600 }}>ID</th>
            <th style={{ textAlign: 'left', padding: '0.625rem 0.75rem', color: '#666', fontWeight: 600 }}>Name</th>
            <th style={{ textAlign: 'right', padding: '0.625rem 0.75rem', color: '#666', fontWeight: 600 }}>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eaeaea' }}>
              <td style={{ padding: '0.75rem', color: '#999' }}>{product.id}</td>
              <td style={{ padding: '0.75rem' }}>{product.name}</td>
              <td style={{ padding: '0.75rem', textAlign: 'right' }}>${product.price.toLocaleString()}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}

